  "runtimeScenarios": [
    {
      "id": "late-claim",
      "events": [
        "A generation 7 claim held before Core",
        "B generation 8 fence commits",
        "B lease becomes active",
        "A claim reaches Core"
      ],
      "expected": "A claim refused without dispatch, B keeps working, and no invocation is reassigned or re-run on A behalf",
      "owner": "rulith-cloud gateway lease wiring plus rulith Core fence check inside the Board lock",
      "test": "cloud: gateway worker fence supersedes late claim; core: fence_refuses_late_claim_in_board_lock",
      "status": "open"
    },
    {
      "id": "duplicate-worker",
      "events": [
        "A has active lease",
        "B presents copied Connection secret with new process id"
      ],
      "expected": "B refused before any Manifest or Tool lock change, with no identifying detail about the current holder in the refusal",
      "owner": "rulith-cloud gateway lease wiring",
      "test": "cloud: gateway refuses second worker while lease is held",
      "status": "open"
    },
    {
      "id": "reference-cross-invocation",
      "events": [
        "invocation 1 uploads, retains and reports its reference",
        "invocation 2 reports that same reference"
      ],
      "expected": "the second report is refused whole; the object keeps exactly the retention invocation 1 legitimately holds, because refusing a forged report is not a release; return to temporary retention needs authoritative confirmation of no reference and no pending retain request, and nothing is physically collected here",
      "owner": "rulith-cloud gateway artifact resolution plus rulith Core reference commit",
      "test": "cloud: gateway refuses foreign artifact reference and preserves the original retain",
      "status": "open"
    },
    {
      "id": "source-free-upload",
      "events": [
        "an action with an empty sourceRecordId produces a large result",
        "the Worker attempts to send the object off the machine"
      ],
      "expected": "refused by name as source_permission_required, both at the Worker before bytes leave and at the Gateway on arrival; the refusal must not come from a policy lookup that merely found nothing, and arriving bytes never count as permission",
      "owner": "rulith-runtime worker upload path plus rulith-cloud gateway upload admission",
      "test": "runtime: worker refuses off-machine upload without granted source permission; cloud: gateway refuses source-free upload by name",
      "status": "open"
    },
    {
      "id": "failure-diagnostic-retention",
      "events": [
        "an action fails and reports a diagnostic reference",
        "Core commits the failure receipt with that reference"
      ],
      "expected": "the diagnostic object follows the existing retention rule with no new permanent-retention claim; it stays uncollectable while Core references it, and not having entered a proof does not mean no execution audit reference exists",
      "owner": "rulith-cloud gateway retention accounting plus rulith Core receipt commit",
      "test": "cloud: failure receipt reference is retained under the existing rule",
      "status": "open"
    },
    {
      "id": "duplicate-artifact-reference",
      "events": [
        "a report names the same reference twice",
        "the Gateway resolves metadata for each named reference"
      ],
      "expected": "refused by name at the resolution step as artifact_reference_repeated, before any array reaches Core; the array constraint cannot decide this, because two entries for one reference carry different metadata and are therefore different objects, and letting one through would give a single reference two truths inside the same result digest",
      "owner": "rulith-cloud gateway artifact resolution",
      "test": "cloud: gateway refuses a repeated artifact reference in one report",
      "status": "open"
    },
    {
      "id": "duplicate-tool-id",
      "events": [
        "a poll presents two descriptors sharing one Tool id with different pins",
        "the Gateway parses the Manifest after admitting the lease"
      ],
      "expected": "refused by name at the Poll parser as tool_manifest_repeats_id, leaving the existing Tool lock untouched; the array constraint cannot decide this, because two descriptors differing in their pin are different objects, and admitting one would let a single Tool id name two local implementations that the Connection lock could not tell apart. The Gateway refuses a repeated id today, so this pins behaviour that already exists rather than asking for new behaviour; what is open is that no test yet checks it against this shared fixture",
      "owner": "rulith-cloud gateway Poll Manifest parser",
      "test": "cloud: gateway refuses a Manifest that repeats a Tool id",
      "status": "open"
    },
    {
      "id": "action-work-source-bound",
      "owner": "rulith-cloud + rulith-runtime + rulith",
      "test": "private Poll action projection and real Worker execution",
      "status": "open",
      "events": [
        "Core lists a Source-bound invocation without a Case envelope",
        "Gateway projects the row and signs the exact served bytes",
        "Worker validates the grant and resolves args.source on its authenticated Connection"
      ],
      "expected": "The same work/tool identity and byte strings survive every hop; target is explicitly empty when absent upstream, static spec.source and shadow grant objects are rejected, and the current Source permission is checked before execution."
    },
    {
      "id": "action-work-source-free",
      "owner": "rulith-cloud + rulith-runtime + rulith",
      "test": "private Poll action projection and real Worker execution",
      "status": "open",
      "events": [
        "Core resolves a Source-free invocation to its sole carrier",
        "Gateway emits sourceRecordId empty without looking up a Source",
        "Worker executes only the authorized local Tool without Source credentials"
      ],
      "expected": "The Source-free row is admitted under the existing Tool authorization, without inventing a Source or borrowing Connection accreditation. An args.source selector is refused before the external effect; ordinary business facts still require a valid Source."
    },
    {
      "id": "self-signed-grant-is-not-dispatch-evidence",
      "owner": "rulith-cloud gateway upload admission plus rulith Core dispatched record",
      "test": "cloud: gateway upload refuses a grant with no trusted Core dispatch behind it",
      "status": "open",
      "events": [
        "a Worker mints a grant for an invocation Core never dispatched, signing it with the Connection key it legitimately holds",
        "the Worker presents that grant on the private upload path together with bytes"
      ],
      "expected": "Refused. The signature verifies, and that proves only that this Connection wrote the token: the Worker holds the same key the Gateway signs with, so grant validity can never stand in for dispatch. Admission starts from Core's own trusted dispatched record for the invocation, recomputes the request identity from the Source, Tool pin and lease in force now, requires it to equal the identity the grant states, and hashes the bytes actually received instead of believing the declared digest. Bytes already received are not authorization, and no object is retained and no reference is issued for a grant that survives only its own signature check."
    },
    {
      "id": "upload-digest-mismatch",
      "owner": "rulith-cloud gateway upload admission",
      "test": "cloud: mismatched upload digest is refused before existing-reference deduplication",
      "status": "open",
      "events": [
        "an authorized dispatched invocation already retained bytes A with digest A",
        "the Worker uploads bytes B claiming digest A"
      ],
      "expected": "artifact_digest_mismatch before deduplication or any reference return; the retained A stays unchanged and no B object or retain is published."
    },
    {
      "id": "undeliverable-large-result",
      "owner": "rulith-cloud gateway upload admission plus rulith Core execution record and rulith-runtime worker",
      "test": "cloud: an object that cannot be retained yields a visible refusal and no receipt; core: the invocation stays open and blocks a non-completed close",
      "status": "open",
      "events": [
        "an action produces a result larger than the inline budget",
        "the object cannot be delivered: the Source permission refuses it, or retention fails after admission"
      ],
      "expected": "No result is manufactured in either direction. The Worker gets a visible refusal naming the reason, reports no succeeded and no failed receipt for work whose outcome it cannot state, and does not rerun the action by itself. Any partial retain stays pending and uncollected rather than being released, and the invocation stays open and keeps blocking a non-completed CloseCase of the roots that reference it. Settling it needs the ordinary route and nothing new: an operator advances the Worker fence past the recorded instance and records ReconcileUnknownExecution, which certifies nothing, and the object is reconciled by hand. This adds no third outcome state, no withheld or truncated result entity, no new Tool and no automatic retry. The fence isolates the whole Connection worker generation, including every outstanding work item dispatched to that instance; each unresolved invocation needs its own disposition. It does not terminate the external process or prove its side effects stopped. Core must still verify its existing advanced-fence prerequisite."
    }
  ],
