  "actionWorkUploadInvariants": {
    "schemaRef": "docs/specs/schemas/rulith-worker-protocol-v2.schema.json#/$defs/WorkerActionWorkItem",
    "rule": "Every arm is a shape-legal row and tests object-storage routing only. Bounded inline results and facts do cross the network and remain subject to existing Tool and Source disclosure authorization; an inline outcome below does not establish that authorization. Artifact object bytes leave only when sourceUpload names this row own Source, permission is granted, upload is true and refusal is absent. Object permission is checked before object size and does not enlarge any budget.",
    "layers": [
      "gateway-projection",
      "worker-before-bytes-leave",
      "gateway-upload-admission"
    ],
    "layerNote": "A refusal is reached twice on purpose. The Worker reaches it before bytes leave, and the Gateway reaches it again on arrival, because bytes already received are never authorization. A decision naming a Source other than the row's own is additionally a fault of gateway-projection: no correct Gateway emits such a row, and the consumers refuse it because a wrong row must not become a silent allow. Missing or malformed row fields are not on this axis at all — those are refused by the row shape as a configuration or protocol fault, and they must never read as a Source decision that defaulted to permitted.",
    "arms": [
      {
        "id": "granted-source-uploads",
        "work": "inv_read_note",
        "change": {},
        "resultBytes": 1048576,
        "outcome": "upload",
        "refusal": null,
        "refusedBy": [],
        "why": "The one decision this row carries names this row's Source, is granted, permits upload and names no refusal. That is the whole of what admits bytes."
      },
      {
        "id": "small-result-uses-ordinary-disclosure",
        "work": "inv_read_note",
        "change": {},
        "resultBytes": 512,
        "outcome": "inline",
        "refusal": null,
        "refusedBy": [],
        "why": "The result stays within the inline budget and is not stored as an Artifact object. It still crosses the network in the ordinary report; existing Tool and Source disclosure authorization must allow that report independently."
      },
      {
        "id": "source-free-row-cannot-send-an-object",
        "work": "inv_pure_sum",
        "change": {},
        "resultBytes": 1048576,
        "outcome": "refused",
        "refusal": "source_permission_required",
        "refusedBy": [
          "worker-before-bytes-leave",
          "gateway-upload-admission"
        ],
        "why": "A Source-free row has no Source record to hold a permission, so its decision is absent by construction. It is refused under the absent name, not as a lookup that found nothing and not as a default that let it through."
      },
      {
        "id": "recorded-denial",
        "work": "inv_read_note",
        "change": {
          "sourceUpload": {
            "sourceRecordId": "docs-a",
            "permission": "denied",
            "upload": false,
            "refusal": "source_off_machine_denied"
          }
        },
        "resultBytes": 1048576,
        "outcome": "refused",
        "refusal": "source_off_machine_denied",
        "refusedBy": [
          "worker-before-bytes-leave",
          "gateway-upload-admission"
        ],
        "why": "A governed refusal that was actually recorded keeps its own name, distinct from the absent one, so the day a policy key is renamed is visible instead of silent."
      },
      {
        "id": "no-permission-record",
        "work": "inv_read_note",
        "change": {
          "sourceUpload": {
            "sourceRecordId": "docs-a",
            "permission": "absent",
            "upload": false,
            "refusal": "source_permission_required"
          }
        },
        "resultBytes": 1048576,
        "outcome": "refused",
        "refusal": "source_permission_required",
        "refusedBy": [
          "worker-before-bytes-leave",
          "gateway-upload-admission"
        ],
        "why": "A registered Source with no upload permission is refused exactly like an unregistered one: the absence is the answer, and it has a name."
      },
      {
        "id": "permission-names-another-source",
        "work": "inv_read_note",
        "change": {
          "sourceUpload": {
            "sourceRecordId": "docs-b",
            "permission": "granted",
            "upload": true,
            "refusal": null
          }
        },
        "resultBytes": 1048576,
        "outcome": "refused",
        "refusal": "source_permission_required",
        "refusedBy": [
          "gateway-projection",
          "worker-before-bytes-leave",
          "gateway-upload-admission"
        ],
        "why": "The row shape accepts this: a granted decision is a granted decision, and no schema can compare it with the row's own sourceRecordId or with the Source inside the signed grant. It is a permission for some other Source, so for this row there is none, and it is refused under the absent name. This is the arm that decides whether a consumer really compares the identity or only reads the verdict."
      },
      {
        "id": "source-free-row-with-a-borrowed-permission",
        "work": "inv_pure_sum",
        "change": {
          "sourceUpload": {
            "sourceRecordId": "docs-a",
            "permission": "granted",
            "upload": true,
            "refusal": null
          }
        },
        "resultBytes": 1048576,
        "outcome": "refused",
        "refusal": "source_permission_required",
        "refusedBy": [
          "gateway-projection",
          "worker-before-bytes-leave",
          "gateway-upload-admission"
        ],
        "why": "The Source-free case of the same fault. A Source-free action gains no accreditation, and attaching another Source's permission to it is exactly the borrowing the empty sourceRecordId exists to make impossible."
      },
      {
        "id": "granted-but-upload-withheld",
        "work": "inv_read_note",
        "change": {
          "sourceUpload": {
            "sourceRecordId": "docs-a",
            "permission": "granted",
            "upload": false,
            "refusal": "source_off_machine_denied"
          }
        },
        "resultBytes": 1048576,
        "outcome": "refused",
        "refusal": "source_off_machine_denied",
        "refusedBy": [
          "worker-before-bytes-leave",
          "gateway-upload-admission"
        ],
        "why": "Granted is not the whole test. Both halves are required, so a decision that grants the Source generally while withholding off-machine upload refuses, under the refusal it names."
      },
      {
        "id": "granted-without-a-named-refusal",
        "work": "inv_read_note",
        "change": {
          "sourceUpload": {
            "sourceRecordId": "docs-a",
            "permission": "granted",
            "upload": false
          }
        },
        "resultBytes": 1048576,
        "outcome": "refused",
        "refusal": "source_permission_required",
        "refusedBy": [
          "worker-before-bytes-leave",
          "gateway-upload-admission"
        ],
        "why": "Upload false with no refusal identity cannot be told apart from an unconfigured lookup, which is the one thing the refusal field exists to prevent. It refuses, and under the name for having no usable permission rather than a name it never stated."
      },
      {
        "id": "granted-that-also-names-a-refusal",
        "work": "inv_read_note",
        "change": {
          "sourceUpload": {
            "sourceRecordId": "docs-a",
            "permission": "granted",
            "upload": true,
            "refusal": "source_off_machine_denied"
          }
        },
        "resultBytes": 1048576,
        "outcome": "refused",
        "refusal": "source_permission_required",
        "refusedBy": [
          "worker-before-bytes-leave",
          "gateway-upload-admission"
        ],
        "why": "A decision that permits and refuses at once says two things, and no permission can be read out of it. Resolving the contradiction toward the permissive half is how a corrupted or half-migrated record becomes an allow."
      },
      {
        "id": "budget-is-not-permission",
        "work": "inv_read_note",
        "change": {
          "sourceUpload": {
            "sourceRecordId": "docs-a",
            "permission": "denied",
            "upload": false,
            "refusal": "source_off_machine_denied"
          },
          "artifactPolicy": {
            "inlineBytes": 8192,
            "readBytes": 65536,
            "objectBytes": 67108864,
            "totalBytes": 1073741824,
            "temporaryRetentionMs": 86400000
          }
        },
        "resultBytes": 1048576,
        "outcome": "refused",
        "refusal": "source_off_machine_denied",
        "refusedBy": [
          "worker-before-bytes-leave",
          "gateway-upload-admission"
        ],
        "why": "Room in every budget, and still nothing leaves. Quota is capacity, not authorization; enlarging the policy is not a route around a Source that refuses."
      },
      {
        "id": "permission-is-not-budget",
        "work": "inv_read_note",
        "change": {},
        "resultBytes": 16777216,
        "outcome": "undeliverable",
        "refusal": null,
        "refusedBy": [],
        "disposition": "undeliverable-large-result",
        "why": "The mirror of the arm above. The Source permits off-machine upload and the object still exceeds the policy in force, so it cannot be delivered. There is no third result state for this: the refusal is visible, no receipt is manufactured, and the invocation stays open under the named scenario."
      },
      {
        "id": "denial-decides-before-size",
        "work": "inv_read_note",
        "change": {
          "sourceUpload": {
            "sourceRecordId": "docs-a",
            "permission": "denied",
            "upload": false,
            "refusal": "source_off_machine_denied"
          }
        },
        "resultBytes": 16777216,
        "outcome": "refused",
        "refusal": "source_off_machine_denied",
        "refusedBy": [
          "worker-before-bytes-leave",
          "gateway-upload-admission"
        ],
        "why": "Both axes object, and the permission is reached first, before any byte leaves. Reporting the size instead would tell an operator to raise a budget for an object that was never allowed to move."
      },
